/**
 * The quote block at the head of a sent message, made clickable: clicking it
 * jumps back to the message the block answers.
 *
 * The block is generated by `buildQuotedSelectionsBlock` and used to render as
 * plain markdown; this component keeps that exact look (the blockquote still
 * goes through the same markdown renderer) and layers the jump affordance on
 * top. It is an inline control inside the message body, so it speaks the app's
 * inline action language — pointer cursor, a hover title, keyboard activation —
 * and introduces no new colour or spacing token. Without a jump handler it
 * renders exactly as the plain blockquote did.
 */

import React from 'react';
import { i18nService } from '../../services/i18n';
import MarkdownContent from '../MarkdownContent';
import { mapWechatBracketCodesForDisplay } from '../chat/wechatEmojiDisplay';

interface CoworkSentQuoteBlockProps {
  /** The raw blockquote markdown (label + excerpt + optional truncation note). */
  block: string;
  /** Jump back to the quoted message. Omitted → the block stays a plain preview. */
  onJump?: () => void;
}

const CoworkSentQuoteBlock: React.FC<CoworkSentQuoteBlockProps> = ({ block, onJump }) => {
  const interactive = Boolean(onJump);
  const label = i18nService.t('coworkQuoteJumpToMessage');
  return (
    <div
      data-cowork-sent-quote="true"
      {...(interactive
        ? {
            role: 'button',
            tabIndex: 0,
            'aria-label': label,
            title: label,
          }
        : {})}
      onClick={interactive ? () => onJump?.() : undefined}
      onKeyDown={interactive
        ? (event: React.KeyboardEvent) => {
            if (event.key === 'Enter' || event.key === ' ') {
              event.preventDefault();
              onJump?.();
            }
          }
        : undefined}
      className={interactive ? 'cursor-pointer' : undefined}
    >
      {/* Same display-only contract as the bubble body beside it: the excerpt
          is message content, so WeChat bracket codes map to emoji and catalog
          emoji render as bundled Twemoji — the stored text stays untouched. */}
      <MarkdownContent
        content={mapWechatBracketCodesForDisplay(block)}
        className="cowork-sent-quote-line max-w-none [overflow-wrap:anywhere]"
        emojiImages
      />
    </div>
  );
};

export default CoworkSentQuoteBlock;
